query:
fragment ResearchDocumentService on ResearchDocument {
  id
  publicationDate
  pageCount
  title
  subtitle
  synopsis
  relevanceInfo
  documentType
  assetClasses
  publications {
    results {
      id
      __typename
    }
    __typename
  }
  __typename
}

fragment PhotoDetails on PhotoDetails {
  type
  url
  width
  height
  focalPointX
  focalPointY
  __typename
}

fragment VideoDetails on ResearchDocument {
  videoDetails {
    mediaId
    thumbnail(size: LARGE) {
      width
      height
      url
      type
      __typename
    }
    __typename
  }
  __typename
}

query companyArticlesQueryFilters($companyId: [String], $item: CompanyItem, $aggregations: [ResearchAggregationDetails], $sortOrder: ResearchSortOrder, $researchQueryNodeChildren: [ResearchQueryNode], $start: Int, $startDate: String, $endDate: String, $searchText: String, $exactMatch: Boolean) {
  companyService {
    companies(q: {queryNode: {operator: EQUALS, item: $item, values: $companyId}}) {
      results {
        research(
          q: {queryNode: {operator: AND, children: $researchQueryNodeChildren}, options: {aggregations: $aggregations, count: 20, start: $start, sortOrder: $sortOrder, sortDirection: DESCENDING, exactMatch: $exactMatch}, startDate: $startDate, endDate: $endDate, searchText: $searchText}
        ) {
          count
          results {
            ...ResearchDocumentService
            ...VideoDetails
            analysts {
              results {
                displayName
                firstName
                lastName
                email
                nonEnglishFirstName
                sid
                primary
                active
                publishingAnalyst
                phoneNumber
                phoneNumberLink: phoneNumber
                teamName
                photo: photo(width: 64, type: ANALYST_PROFILE_PHOTO) {
                  ...PhotoDetails
                  __typename
                }
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
